// src/lib/mcp/tools/list-governance.ts
import { defineTool as defineTool3 } from "npm:@lovable.dev/mcp-js@0.26.1";
import { z as z2 } from "npm:zod@^3.25.76";
var list_governance_default = defineTool3({
  name: "list_governance",
  title: "List governance",
  description: "List the people in SociisGroup's published governance structure: the Executive Leadership Team, contributors, and the advisory council.",
  inputSchema: {
    group: z2.enum(["leadership", "contributors", "council", "all"]).default("all").describe("Which part of the governance structure to return.")
  },
  annotations: { readOnlyHint: true, idempotentHint: true, openWorldHint: false },
  handler: ({ group }) => {
    const people = group === "all" ? PEOPLE : PEOPLE.filter((p) => p.group === group);
    const text = people.map((p) => `${p.name} \u2014 ${p.role} (${p.group})`).join("\n");
    return {
      content: [{ type: "text", text: text || "No people found for that group." }],
      structuredContent: { people }
    };
  }
});

// src/lib/mcp/tools/list-places.ts
import { defineTool as defineTool4 } from "npm:@lovable.dev/mcp-js@0.26.1";
import { z as z3 } from "npm:zod@^3.25.76";
var list_places_default = defineTool4({
  name: "list_places",
  title: "List places",
  description: "List the cities and houses in SociisGroup's published place map, with stewardship, wave and status. Houses named are screened candidates.",
  inputSchema: {
    status: z3.enum(["home", "confirmed", "candidate", "all"]).default("all").describe("Filter by place status."),
    query: z3.string().optional().describe("Optional case-insensitive match on city, country or house name.")
  },
  annotations: { readOnlyHint: true, idempotentHint: true, openWorldHint: false },
  handler: ({ status, query }) => {
    const needle = query?.trim().toLowerCase();
    const places = PLACES.filter((p) => status === "all" || p.status === status).filter(
      (p) => needle ? `${p.city} ${p.country} ${p.house}`.toLowerCase().includes(needle) : true
    );
    const text = places.map(
      (p) => `${p.city}, ${p.country} \u2014 ${p.house || "house not yet named"}${p.stewardship ? ` (${p.stewardship})` : ""} \xB7 ${p.wave} \xB7 ${p.status} \xB7 ${p.note}`
    ).join("\n");
    return {
      content: [{ type: "text", text: text || "No places matched that filter." }],
      structuredContent: { places }
    };
  }
});

